-- Seed of the metric catalogue: the metric_keys the data team must produce. Polish labels are a first
-- draft and need a native-speaker review. Identical in both city schemas.
on conflict (metric_key) do update set
  category=excluded.category, label_en=excluded.label_en, label_pl=excluded.label_pl,
  description_en=excluded.description_en, unit=excluded.unit, higher_is=excluded.higher_is,
  refresh_cadence=excluded.refresh_cadence, default_data_kind=excluded.default_data_kind, sort_order=excluded.sort_order;
